import{_ as t,o as d,c as a,a3 as s}from"./chunks/framework.B7pF4b99.js";const u=JSON.parse('{"title":"本機與遠端整合（2026-11-10）","description":"","frontmatter":{},"headers":[],"relativePath":"merge-2026-11-10.md","filePath":"merge-2026-11-10.md","lastUpdated":1794274556000}'),l={name:"merge-2026-11-10.md"};function i(o,e,r,n,c,p){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="本機與遠端整合-2026-11-10" tabindex="-1">本機與遠端整合（2026-11-10） <a class="header-anchor" href="#本機與遠端整合-2026-11-10" aria-label="Permalink to &quot;本機與遠端整合（2026-11-10）&quot;">​</a></h1><p>本機基底為 <code>544e202</code>，未提交工作先保存為 <code>0803032</code>；遠端合併來源為 <code>4177adb</code>。合併保留雙方提交歷史。</p><table tabindex="0"><thead><tr><th>範圍</th><th>本機工作</th><th>遠端更新</th><th>合併結果</th></tr></thead><tbody><tr><td>開機與模組</td><td>舊版平面目錄、QEMU <code>-kernel</code></td><td>模組分層、flash 載入 WUFS 的 <code>/boot/kernel.elf</code></td><td>保留遠端目錄與兩種開機入口</td></tr><tr><td>Block</td><td>明確裝置所有權、完成檢查、計數</td><td>per-device gate/event/bounce、非同步等待、有界 reset/offline</td><td>採遠端生命週期，加上本機診斷計數；IRQ/poll 共用完成檢查</td></tr><tr><td>外部中斷</td><td>有界 FDT 解析、PLIC 路由與派發</td><td>以 scheduler polling 收集裝置事件</td><td>移植為 <code>arch/riscv/fdt.*</code> 與 <code>irq.*</code>，保留 polling 備援</td></tr><tr><td>FS／VM 同步</td><td>排序 KernelMutex、FIFO ownership handoff</td><td>KernelGate、取消延遲、VM pin/revoke、WUFS journal</td><td>runtime 使用遠端 gate；mutex 與主機測試保留為獨立原型</td></tr><tr><td>使用介面與文件</td><td>PLIC／請求原型規格</td><td>多視窗 Terminal、互動教學與網站</td><td>保留遠端功能，補上整合註記與目前驗證範圍</td></tr></tbody></table><p>PLIC callback 先 ACK VirtIO，再呼叫共用 <code>poll_device</code>，最後由 dispatcher complete PLIC claim。Callback 不睡眠、不輸出、不切換行程、不歸還 DMA buffer；event 通知可把等待者排入 Ready queue。<code>process_wait_allowed</code> 拒絕 IRQ context。Kernel 全域中斷及單 hart 政策不變。未支援裝置樹或 PLIC 路由時沿用 polling。</p><p><code>ps</code> 顯示 PLIC handled/spurious、unhandled/invalid/budget，以及每顆磁碟的 state、submitted/completed、io_errors/protocol_errors、offline。正常閒置時 submitted/completed 相等；發生 reset/offline 後，失敗提交可能沒有正常 used-ring completion，不保證兩者相等。</p><p>本機兩份 Spec 32／33 保留合併前設計背景與原編號；與遠端同號文件以檔名區分。其同步等待、直接 fail-stop 和「尚未編譯」描述屬歷史階段，現況以本文為準。<code>kernel/proc/kmutex.*</code> 沒有接入 runtime，不可把它的主機測試當成 FS／VM gate 或 RV64 context-switch 驗證。</p><p>編譯時另移除遠端 FS 內只有賦值、沒有讀取的 <code>format_version</code>，以通過 portable Clang 23 的 <code>-Wall -Wextra -Werror</code>。</p><h2 id="開機入口" tabindex="-1">開機入口 <a class="header-anchor" href="#開機入口" aria-label="Permalink to &quot;開機入口&quot;">​</a></h2><p>Windows PowerShell 在 <code>D:\\WUWAOS</code>，使用現有 portable 環境：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gui     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 原生 QEMU 圖形視窗</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # UART；QEMU 直接載入核心</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>真正從 WUFS 磁碟載入核心，可先執行 <code>.\\Start-WUWAOS.cmd shell</code>，再於 Bash 輸入：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run-disk</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>該模式使用唯讀 <code>build/boot-flash.img</code> 與 <code>build/wuwaos-cli.img</code>，由 OpenSBI → flash loader → <code>/boot/kernel.elf</code> 啟動 CLI，不使用 QEMU <code>-kernel</code>。文字模式按 Ctrl+A，放開後按 X 結束。圖形模式關閉 QEMU 視窗。使用同一映像時先結束前一個 session。</p><h2 id="驗證" tabindex="-1">驗證 <a class="header-anchor" href="#驗證" aria-label="Permalink to &quot;驗證&quot;">​</a></h2><ul><li>Portable 工具檢查通過；QEMU 11.1.3、Clang／LLD／LLVM 23.1.4。</li><li>RV64 kernel、strip 後的磁碟核心與 flash loader 編譯通過。</li><li><code>.\\Test-KernelMutex.cmd</code> 四組主機測試通過。</li><li>QEMU 11.1.3／OpenSBI 1.8.1 以 serial TCP 執行 smoke checks，使用獨立測試映像；未修改日常使用的磁碟。</li><li><code>build/merge-smoke-20261110-093314/</code>：直接 <code>-kernel</code> 開機、WUFS／swap 順序互換、flash → WUFS 磁碟開機均通過。驗證 <code>ps → ls /boot → ps</code> 的 WUFS handled 增加、IRQ 錯誤為零，以及閒置磁碟 submitted/completed 相等。</li><li>同一組紀錄也驗證檔案寫入與跨兩次重啟讀回、pipe、<code>demo sync</code>、heap 配置／寫入／讀取／釋放。直接開機結束時 WUFS submitted/completed 均為 34058，swap 均為 2，io_errors/protocol_errors 均為零；此為基本路徑檢查，不包含 swap 壓力測試。</li><li><code>build/merge-smoke-20261110-093408/</code>：有效磁碟正常掛載且 SHA-256 不變；空白磁碟完成初始化並有 WUFS0002 標記；檔頭損壞與最後一 byte 非零的磁碟均拒絕格式化且 SHA-256 不變。空白案例等到 shell 出現才關閉 QEMU，以確保初始化已結束。</li><li>VitePress 文件網站建置通過，只有既有 bundle size 提醒。測試腳本與原始 console logs 留在上述本機 <code>build/</code>；未將工具包、磁碟或測試輸出提交到 Git。</li><li>GUI 互動、損壞 completion／reset timeout／中斷風暴故障注入，以及全面 journal crash recovery 不在本次 smoke test 範圍；先前未驗項目維持 NOT_RUN。</li></ul>`,15)])])}const m=t(l,[["render",i]]);export{u as __pageData,m as default};
